    <script>
      const state = {
        submitted: false,
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
      };

      const formConfig = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          required: true,
          autocomplete: "name",
          placeholder: "Ada Lovelace",
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          required: true,
          autocomplete: "email",
          placeholder: "ada@example.com",
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          required: false,
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          helperText: "Include a country code and spaces or dashes, for example +1 555 123 4567.",
        },
      ];

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getError(id, value) {
        const trimmed = value.trim();

        if (id === "fullName" && !trimmed) {
          return "Please enter your full name.";
        }

        if (id === "email") {
          if (!trimmed) {
            return "Please enter your email address.";
          }

          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
            return "Please enter a valid email address.";
          }
        }

        return "";
      }

      function getFormErrors() {
        return formConfig.reduce((errors, field) => {
          const error = field.required ? getError(field.id, state.values[field.id]) : "";
          if (error) {
            errors[field.id] = error;
          }
          return errors;
        }, {});
      }

      function fieldMarkup(field, errorMessage) {
        const hasError = Boolean(errorMessage);
        const helpId = `${field.id}-help`;
        const errorId = `${field.id}-error`;
        const describedBy = [field.helperText ? helpId : null, hasError ? errorId : null].filter(Boolean).join(" ");
        const requiredMark = field.required
          ? '<span class="required-mark" aria-hidden="true"> *</span><span class="sr-only"> required</span>'
          : "";

        return `
          <div class="form-field" data-invalid="${hasError ? "true" : "false"}">
            <label for="${field.id}">${escapeHtml(field.label)}${requiredMark}</label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              ${field.required ? "required" : ""}
              autocomplete="${field.autocomplete}"
              placeholder="${escapeHtml(field.placeholder)}"
              value="${escapeHtml(state.values[field.id])}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${hasError ? 'aria-invalid="true"' : ""}
            />
            ${field.helperText ? `<p class="field-help" id="${helpId}">${escapeHtml(field.helperText)}</p>` : ""}
            <p class="field-error" id="${errorId}" ${hasError ? "" : 'hidden aria-hidden="true"'}>${escapeHtml(errorMessage || "")}</p>
          </div>
        `;
      }

      function App() {
        const errors = state.submitted ? getFormErrors() : {};

        return `
          <div class="page-shell">
            <section class="hero" aria-labelledby="support-heading">
              <p class="eyebrow">Support</p>
              <h1 id="support-heading">Contact our support team</h1>
              <p class="lead">
                Send us your details and we&apos;ll get back to you as soon as possible.
                The form keeps required fields clear and only shows validation feedback after you try to submit it.
              </p>
            </section>

            <section class="form-card" aria-labelledby="form-heading">
              <h2 id="form-heading" class="eyebrow" style="margin-top:0;">Request help</h2>
              <p class="form-status" id="form-status" aria-live="polite"></p>
              <form id="contact-form" novalidate>
                ${formConfig.map((field) => fieldMarkup(field, errors[field.id] || "")).join("")}
                <div class="actions">
                  <button type="submit">Send message</button>
                </div>
              </form>
            </section>
          </div>
        `;
      }

      function render() {
        document.querySelector("main").innerHTML = App();
        bindForm();
      }

      function syncFieldValidation(fieldName) {
        const field = formConfig.find((item) => item.id === fieldName);
        const input = document.getElementById(fieldName);
        const fieldWrapper = input?.closest(".form-field");
        const errorNode = document.getElementById(`${fieldName}-error`);
        if (!field || !input || !fieldWrapper || !errorNode) {
          return;
        }

        const errorMessage = field.required ? getError(fieldName, state.values[fieldName]) : "";
        const hasError = Boolean(errorMessage);

        fieldWrapper.dataset.invalid = hasError ? "true" : "false";
        input.setAttribute("aria-invalid", hasError ? "true" : "false");

        if (hasError) {
          errorNode.textContent = errorMessage;
          errorNode.hidden = false;
          errorNode.removeAttribute("aria-hidden");
        } else {
          errorNode.textContent = "";
          errorNode.hidden = true;
          errorNode.setAttribute("aria-hidden", "true");
        }
      }

