         const errors = state.submitted ? getFormErrors() : {};

         return `
           <div class="page-shell">
             <section class="hero" aria-labelledby="support-heading">
               <p class="eyebrow">Support</p>
               <h1 id="support-heading">Contact our support team</h1>
               <p class="lead">
                 Send us your details and we&apos;ll get back to you as soon as possible.
                 The form keeps required fields clear and only shows validation feedback after you try to submit it.
               </p>
             </section>

             <section class="form-card" aria-labelledby="form-heading">
               <h2 id="form-heading" class="eyebrow" style="margin-top:0;">Request help</h2>
               <p class="form-status" id="form-status" aria-live="polite"></p>
               <form id="contact-form" novalidate>
                 ${formConfig.map((field) => fieldMarkup(field, errors[field.id] || "")).join("")}
                 <div class="actions">
                   <button type="submit">Send message</button>
                 </div>
               </form>
             </section>
           </div>
         `;
       }

       function render() {
         document.querySelector("main").innerHTML = App();
         bindForm();
       }

       function syncFieldValidation(fieldName) {
         const field = formConfig.find((item) => item.id === fieldName);
         const input = document.getElementById(fieldName);
         const fieldWrapper = input?.closest(".form-field");
         const errorNode = document.getElementById(`${fieldName}-error`);
         if (!field || !input || !fieldWrapper || !errorNode) {
           return;
         }

         const errorMessage = field.required ? getError(fieldName, state.values[fieldName]) : "";
         const hasError = Boolean(errorMessage);

         fieldWrapper.dataset.invalid = hasError ? "true" : "false";
         if (hasError) {
           input.setAttribute("aria-invalid", "true");
         } else {
           input.removeAttribute("aria-invalid");
         }

         if (hasError) {
           errorNode.textContent = errorMessage;
           errorNode.hidden = false;
           errorNode.removeAttribute("aria-hidden");
         } else {
           errorNode.textContent = "";
           errorNode.hidden = true;
           errorNode.setAttribute("aria-hidden", "true");
         }
       }

       function bindForm() {
         const form = document.getElementById("contact-form");

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           state.submitted = true;

           const errors = getFormErrors();
           render();

           const firstInvalid = Object.keys(errors)[0];
           const status = document.getElementById("form-status");
           if (firstInvalid) {
             document.getElementById(firstInvalid).focus();
             status.textContent = "Please correct the highlighted fields and try again.";
             return;
           }

           status.textContent = "Your message is ready to send.";
         });

         form.addEventListener("input", (event) => {
           const target = event.target;
           if (!(target instanceof HTMLInputElement)) {
             return;
           }

           state.values[target.name] = target.value;
